func:
var WINDOWS = [
  {start:Date.parse('2025-03-21'),end:Date.parse('2025-05-20'),low:70,med:20,high:10,auc:null,label:'W0 Training'},
  {start:Date.parse('2025-05-21'),end:Date.parse('2025-06-20'),low:70,med:20,high:10,auc:0.64,label:'W1 Stable'},
  {start:Date.parse('2025-06-21'),end:Date.parse('2025-07-20'),low:65,med:22,high:13,auc:0.59,label:'W2 Declining'},
  {start:Date.parse('2025-07-21'),end:Date.parse('2025-08-20'),low:70,med:20,high:10,auc:0.73,label:'W3 Peak'},
  {start:Date.parse('2025-08-21'),end:Date.parse('2025-09-20'),low:65,med:22,high:13,auc:0.64,label:'W4 Stable'},
  {start:Date.parse('2025-09-21'),end:Date.parse('2025-10-20'),low:60,med:25,high:15,auc:0.58,label:'W5 Drift!'},
  {start:Date.parse('2025-10-21'),end:Date.parse('2025-11-20'),low:50,med:28,high:22,auc:0.49,label:'W6 Severe!'},
  {start:Date.parse('2025-11-21'),end:Date.parse('2025-12-20'),low:65,med:22,high:13,auc:0.63,label:'W7 Recovery'},
  {start:Date.parse('2025-12-21'),end:Date.parse('2026-02-01'),low:67,med:20,high:13,auc:0.54,label:'W8 Stabilizing'}
];
var RETRAIN_AT = {6:true, 7:true};
var SIM_START = Date.parse('2025-03-21');
var SIM_END   = Date.parse('2026-02-01');

function findWin(ms) {
  for (var i = WINDOWS.length-1; i >= 0; i--) {
    if (ms >= WINDOWS[i].start) return i;
  }
  return 0;
}

var paused     = flow.get('sim_paused')   || false;
var retraining = flow.get('retraining')  || false;
var speed      = flow.get('sim_speed')    || 1.0;
var virtualMs  = flow.get('virtual_ms')  || SIM_START;
var curWin     = findWin(virtualMs);
var winInfo    = WINDOWS[curWin];
var simDone    = virtualMs >= SIM_END;

var simState = {
  topic: 'sim_state',
  payload: {
    virtual_date: new Date(virtualMs).toISOString().slice(0,10),
    window_index: curWin,
    window_label: winInfo.label,
    window_auc:   winInfo.auc,
    speed:        speed,
    paused:       paused,
    retraining:   retraining,
    sim_done:     simDone,
    approved:     flow.get('approved_count') || 0,
    rejected:     flow.get('rejected_count') || 0,
    pending:      flow.get('pending_count')  || 0,
    windows: WINDOWS.map(function(w,i){ return {label:w.label,auc:w.auc,passed:virtualMs>w.end,current:i===curWin}; }),
    train_pct: (function(){var tEnd=curWin>0?WINDOWS[curWin-1].end:Math.min(virtualMs,WINDOWS[0].end);return Math.min((tEnd-SIM_START)/(SIM_END-SIM_START)*100,100);})(),
    cursor_pct: Math.min((virtualMs-SIM_START)/(SIM_END-SIM_START)*100,100),
    windows_detail: WINDOWS.map(function(w,i){var tot=SIM_END-SIM_START;return{label:w.label,auc:w.auc,start_pct:(w.start-SIM_START)/tot*100,width_pct:(Math.min(w.end,SIM_END)-w.start)/tot*100,passed:virtualMs>w.end,current:i===curWin,retrain_entry:!!(RETRAIN_AT[i])};}) 
  }
};

if (paused || retraining || simDone) {
  return [null, null, simState];
}

var newMs   = virtualMs + speed * 24 * 3600 * 1000;
flow.set('virtual_ms', newMs);
var newWin = findWin(newMs);
flow.set('current_window', newWin);

var retrainMsg = null;
if (newWin !== curWin && RETRAIN_AT[newWin]) {
  var lastR = flow.get('last_retrain_ms') || 0;
  if (newMs - lastR > 25 * 24 * 3600 * 1000) {
    flow.set('last_retrain_ms', newMs);
    flow.set('retraining', true);
    flow.set('sim_paused', true);
    retrainMsg = {payload:{}, headers:{'Content-Type':'application/json'}};
  }
}

var w = WINDOWS[newWin];
var r = Math.random() * 100;
var scenario = r < w.low ? 'LOW_RISK' : (r < w.low + w.med ? 'MEDIUM_RISK' : 'HIGH_RISK');

return [
  {payload:{scenario:scenario}, headers:{'Content-Type':'application/json'}},
  retrainMsg,
  simState
];

var p = msg.payload;
if (!p || p.fraud_probability === undefined) return null;
var tier = p.risk_tier || 'LOW';
if (tier === 'HIGH')        flow.set('rejected_count', (flow.get('rejected_count')||0)+1);
else if (tier === 'MEDIUM') flow.set('pending_count',  (flow.get('pending_count') ||0)+1);
else                        flow.set('approved_count', (flow.get('approved_count')||0)+1);
var eventMsg = {
  topic: 'event',
  payload: { insertion_id: p.insertion_id || '', fraud_probability: p.fraud_probability, risk_tier: tier }
};
// Auto-trigger SHAP for anything that isn't low-risk
var shapMsg = null;
if (tier !== 'LOW' && p.insertion_id) {
  shapMsg = {payload: {insertion_id: p.insertion_id}};
}
return [eventMsg, shapMsg];

var data = msg.payload;
var raw = Array.isArray(data) ? data : (data && data.items ? data.items : []);
var items = raw.map(function(it) {
  var s = it.event_summary || {};
  var prob = (it.fraud_probability !== undefined) ? it.fraud_probability : ((s.score||0)/100);
  return {
    insertion_id:     it.insertion_id || '',
    fraud_probability: prob,
    score_pct:        (prob*100).toFixed(1),
    category:         s.category || s.listing_category || '-',
    price:            s.price    || s.listing_price    || '-',
    ip_country:       s.ip_country || s.seon_ip_country || '-',
    tor:              !!(s.tor || s.seon_tor),
    vpn:              !!(s.vpn || s.seon_vpn),
    disposable:       !!(s.disposable || s.seon_email_disposable),
    queued_at:        (s.queued_at || it.queued_at || '').slice(0,19)
  };
});
return {topic:'queue', payload:items};

var d = msg.payload || {};
return {
  topic: 'drift',
  payload: {
    psi:              d.prediction_psi   || 0,
    overall_drift:    !!d.overall_drift,
    drift_label:      d.drift_label      || 'COLLECTING',
    drifted_features: d.drifted_features || []
  }
};

var s      = msg.payload || {};
var status = (s.status || 'idle').toLowerCase();
var prev   = (flow.get('retrain_status_prev') || 'idle').toLowerCase();
flow.set('retrain_status_prev', status);
if (prev === 'running' && (status === 'completed' || status === 'failed' || status === 'idle')) {
  if (flow.get('retraining')) {
    flow.set('retraining', false);
    flow.set('sim_paused', false);
  }
}
return [
  {topic:'retrain', payload:{
    status:        s.status || 'idle',
    started_at:    s.started_at   || null,
    finished_at:   s.finished_at  || null,
    training_rows: s.training_rows|| 0,
    error:         s.error        || null
  }},
  null
];

var action = (msg.payload || {}).action;
if (action === 'toggle_pause')  return [msg,null,null,null,null,null];
if (action === 'set_speed')     return [null,msg,null,null,null,null];
if (action === 'force_future')  return [null,null,msg,null,null,null];
if (action === 'reset')         return [null,null,null,{payload:{},headers:{'Content-Type':'application/json'}},null,null];
if (action === 'decision')      return [null,null,null,null,msg,null];
if (action === 'request_shap')  return [null,null,null,null,null,msg];
return [null,null,null,null,null,null];

var s = parseFloat((msg.payload||{}).speed) || 1.0;
flow.set('sim_speed', Math.min(8, Math.max(0.25, s)));
return null;

var p = msg.payload || {};
if (!p.insertion_id || !p.decision) return null;
msg.url     = 'http://localhost:8000/admin/decision/' + p.insertion_id;
msg.method  = 'POST';
msg.payload = {decision:p.decision, admin_id:'admin-1', notes:p.notes||''};
msg.headers = {'Content-Type':'application/json'};
return msg;

flow.set('approved_count',    0);
flow.set('rejected_count',    0);
flow.set('pending_count',     0);
flow.set('virtual_ms',        Date.parse('2025-03-21'));
flow.set('sim_speed',         1.0);
flow.set('current_window',    0);
flow.set('retraining',        false);
flow.set('sim_paused',        false);
flow.set('last_retrain_ms',   0);
flow.set('retrain_status_prev','idle');
msg.payload = {};
msg.headers = {'Content-Type':'application/json'};
return msg;

var p = msg.payload || {};
if (!p.insertion_id) return null;
msg.url    = 'http://localhost:8000/admin/shap/' + p.insertion_id;
msg.method = 'POST';
msg.payload = {};
msg.headers = {'Content-Type':'application/json'};
return [
  msg,
  {topic:'shap_loading', payload:{insertion_id: p.insertion_id}}
];

var p = msg.payload || {};
var id = p.insertion_id || msg._shap_id;
if (!id) return null;
return {
  topic: 'shap',
  payload: {
    insertion_id:             id,
    waterfall_chart_base64:   p.waterfall_chart_base64   || null,
    top_fraud_indicators:     p.top_fraud_indicators     || [],
    top_legitimate_indicators:p.top_legitimate_indicators|| [],
    prediction_value:         p.prediction_value         || null,
    message:                  p.message                  || null
  }
};

// Pull an event from 1-2 windows ahead with slight jitter
var DIST = [
  {low:70,med:20,high:10},
  {low:70,med:20,high:10},
  {low:65,med:22,high:13},
  {low:70,med:20,high:10},
  {low:65,med:22,high:13},
  {low:60,med:25,high:15},
  {low:50,med:28,high:22},
  {low:65,med:22,high:13},
  {low:67,med:20,high:13}
];
var cur = flow.get('current_window') || 0;
var ahead = Math.min(cur + 1 + Math.floor(Math.random() * 2), DIST.length - 1);
var d = DIST[ahead];
// ±15% jitter on each bucket then renormalise
function jit(v){ return Math.max(1, v + (Math.random()-0.5)*30); }
var lo=jit(d.low), me=jit(d.med), hi=jit(d.high);
var tot=lo+me+hi; lo/=tot; me/=tot;
var r=Math.random();
// Bias: ensure at least a chance of MEDIUM so it reaches the queue
// If future window is stable this will still occasionally be LOW/HIGH
var scenario = r < lo ? 'LOW_RISK' : (r < lo+me ? 'MEDIUM_RISK' : 'HIGH_RISK');
return {payload:{scenario:scenario}, headers:{'Content-Type':'application/json'}};
